import type { ContextSource } from "#sdk/background/context";
import type { LifecycleObserver } from "#sdk/background/observers";
import { t } from "./i18n.js";

/** A capability factory adapts its read-only Session port to a bounded context source. */
export function taskNoteSource(readNote: (sessionId: string, signal?: AbortSignal) => Promise<string>): ContextSource {
  return { id: "example.task-note", get title() { return t("taskNote"); }, maxChars: 1000, timeoutMs: 500,
    read: request => readNote(request.sessionId, request.signal) };
}

/** Send committed completion identity to an injected sink; conversation text remains private. */
export function completionObserver(record: (sessionId: string, runId: string) => Promise<void>): LifecycleObserver {
  return { id: "example.completions", capacity: 16, timeoutMs: 1000,
    accepts: event => event.type === "agent_end" && event.phase === "committed",
    onEvent: event => record(event.sessionId, event.runId) };
}

import type { ModelMessage, ProviderAdapter } from '#sdk/background/providers';

/** Local adapter for exercising host integrations; it never calls a model service. */
export const deterministicProvider: ProviderAdapter = {
  async chat(messages, _tools, signal) {
    signal?.throwIfAborted();
    return { message: reply(messages) };
  },
  async *chatStream(messages, _tools, signal) {
    signal?.throwIfAborted();
    const message = reply(messages);
    yield { type: 'text_delta', delta: String(message.content) };
    signal?.throwIfAborted();
    yield { type: 'done', message };
  },
};

function reply(messages: ModelMessage[]): ModelMessage {
  const message = [...messages].reverse().find(item => item.role === 'user');
  return { role: 'assistant', content: `Example: ${typeof message?.content === 'string' ? message.content : '(structured input)'}` };
}

import type { LifecycleObserver } from "#sdk/background/observers";
import { completionObserver } from "./context-and-observer.js";

// Replace this local diagnostic sink with your own metrics adapter; no message text is exposed.
export default [completionObserver(async (sessionId, runId) => {
  console.debug("Example task completed", { sessionId, runId });
})] satisfies readonly LifecycleObserver[];

import type { ProviderAdapter } from "#sdk/background/providers";
import { deterministicProvider } from "./deterministic-provider.js";

export default { example: deterministicProvider } satisfies Readonly<Record<string, ProviderAdapter>>;

import type { SkillExtensionAPI } from "#sdk/shared/skill-definition";
import { modelT } from "./model-messages.js";

/** Content-only Skills need no background host or privileged tool binding. */
export default function (qz: SkillExtensionAPI) {
  qz.registerSkill({
    name: "example-reading-guide",
    aliases: ["示例阅读指南", "Example reading guide"],
    get displayName() { return modelT("skillName"); },
    get description() { return modelT("skillDescription"); },
    get content() { return modelT("skillContent"); },
    get resources() { return [{
      path: "references/outline.md",
      type: "reference",
      content: modelT("skillOutline"),
    }]; },
  });
}

import type { ToolExtensionAPI } from "#sdk/background";
import { t } from "./i18n.js";
import { modelT } from "./model-messages.js";
import type { ExampleTableResult } from "./result.js";

/** Shared implementation for the discovered entry and focused execution tests. */
export function registerTableExample(registerTool: ToolExtensionAPI["registerTool"], { rendererId = "table" } = {}) {
  registerTool({
    name: "example_table",
    get title() { return t("dataTitle"); },
    get description() { return modelT("description"); },
    rendererId,
    get parameters() { return {
      type: "object",
      properties: {
        title: { type: "string", description: modelT("title") },
        rows: { type: "array", description: modelT("rows"), items: {
          type: "object",
          properties: {
            label: { type: "string", description: modelT("rowLabel") },
            value: { type: "number", description: modelT("rowValue") },
          },
          required: ["label", "value"],
        } },
      },
      required: ["rows"],
    } as const; },
    execute: ({ title = t("dataTitle"), rows }, signal): ExampleTableResult => {
      signal?.throwIfAborted();
      return { title, rows };
    },
  });
}

import type { ToolExtension } from "#sdk/background";
import { registerTableExample } from "./table-tool.js";

const register: ToolExtension = ({ registerTool }) => {
  registerTableExample(registerTool, { rendererId: "example.value-card" });
};
export default register;

