import { imageT } from './messages.js';

export const IMAGE_MAX_EDGE = 2048;
export const IMAGE_MAX_BYTES = 2 * 1024 * 1024;
export const IMAGE_INPUT_MAX_BYTES = 32 * 1024 * 1024;
export const IMAGE_INPUT_MAX_PIXELS = 64 * 1024 * 1024;
export const MODEL_IMAGE_MAX_BYTES = 48 * 1024 * 1024;
export const MODEL_REQUEST_MAX_BYTES = 64 * 1024 * 1024;

export class ImageLimitError extends Error {
  readonly retryable = false;
  readonly kind = 'invalid_request' as const;
  constructor(readonly code: string, message: string, readonly details: Record<string, unknown> = {}) {
    super(message);
    this.name = 'ImageLimitError';
  }
}

/** Native data-URL decoding owns MIME parameters; callers share only this bounded header parse. */
export function parseImageDataUrlHeader(dataUrl: string) {
  const comma = dataUrl.indexOf(',');
  const header = dataUrl.slice(0, comma);
  const match = /^data:(image\/[a-z0-9.+-]+)(?:;.*)?$/i.exec(header);
  if (comma < 0 || comma > 128 || !match) throw invalidImage();
  return { mimeType: match[1].toLowerCase(), base64: /;base64$/i.test(header), offset: comma + 1 };
}

/** Inspect encoded bytes without allocating a second copy of the base64 payload. */
export function inspectImageDataUrl(dataUrl: string) {
  const { mimeType, base64, offset } = parseImageDataUrlHeader(dataUrl);
  if (!base64) throw invalidImage();
  const length = dataUrl.length - offset;
  if (!length || length % 4 !== 0) throw invalidImage();
  let padding = 0;
  if (dataUrl.endsWith('=')) padding++;
  if (dataUrl.endsWith('==')) padding++;
  for (let index = offset; index < dataUrl.length - padding; index++) {
    const char = dataUrl.charCodeAt(index);
    if (!(char >= 65 && char <= 90) && !(char >= 97 && char <= 122)
      && !(char >= 48 && char <= 57) && char !== 43 && char !== 47) throw invalidImage();
  }
  return { mimeType, bytes: length / 4 * 3 - padding, dataUrlBytes: dataUrl.length };
}

export function assertImageDataUrl(dataUrl: string, { maxBytes = IMAGE_MAX_BYTES } = {}) {
  const image = inspectImageDataUrl(dataUrl);
  assertImageBytes(image.bytes, boundedImageValue(maxBytes, IMAGE_MAX_BYTES));
  return image;
}

export function assertImageBytes(bytes: number, maxBytes = IMAGE_MAX_BYTES, input = false) {
  if (!Number.isFinite(bytes) || bytes <= 0) throw invalidImage();
  if (bytes > maxBytes) throw new ImageLimitError(input ? 'IMAGE_INPUT_TOO_LARGE' : 'IMAGE_TOO_LARGE',
    imageT(input ? 'inputTooLarge' : 'tooLarge', { maxBytes }), { bytes, maxBytes });
}

export function assertImageDimensions(width: number, height: number) {
  if (!(width > 0 && height > 0) || !Number.isFinite(width * height)) throw invalidImage();
  if (width * height > IMAGE_INPUT_MAX_PIXELS || width > 65536 || height > 65536) {
    throw new ImageLimitError('IMAGE_DIMENSIONS_TOO_LARGE', imageT('dimensions'), { width, height, maxPixels: IMAGE_INPUT_MAX_PIXELS });
  }
}

export function boundedImageValue(value: number | undefined, limit: number) {
  return Number.isFinite(value) && Number(value) > 0 ? Math.max(1, Math.min(limit, Math.floor(Number(value)))) : limit;
}

function invalidImage() { return new ImageLimitError('INVALID_IMAGE_DATA', imageT('invalid')); }

/** Keep embedded bytes out of image discovery, read metadata and error envelopes. */
export async function compactImageSource(source: string): Promise<string> {
  if (!/^data:/i.test(source) && source.length <= 8192) return source;
  const digest = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(source));
  const hash = [...new Uint8Array(digest)].map(byte => byte.toString(16).padStart(2, '0')).join('');
  const mime = /^data:(image\/[a-z0-9.+-]+)/i.exec(source)?.[1] || 'image/unknown';
  return `data:${mime};sha256=${hash};chars=${source.length}`;
}

import { existsSync, readFileSync } from "node:fs";
import { resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { parseEnv } from "node:util";

const localEnvFile = fileURLToPath(new URL("../../.env.local", import.meta.url));

// Read only the selected Provider's credential; never load all local secrets into
// process.env, where unrelated test subprocesses could inherit them.
export function readTestApiKey(provider, {
  keyFile = "",
  env = process.env,
  envFile = localEnvFile,
  required = true,
} = {}) {
  const name = `${String(provider).toUpperCase().replace(/-/g, "_")}_API_KEY`;
  let apiKey;
  if (keyFile) {
    apiKey = <REDACTED> "utf8").trim();
  } else {
    const values = env[name] !== undefined
      ? env
      : existsSync(envFile) ? parseEnv(readFileSync(envFile, "utf8")) : {};
    apiKey = <REDACTED> ?? "").trim();
  }
  if (!apiKey && required) {
    throw new Error(`Missing ${name}: set it in .env.local or the environment, or provide an explicit key file`);
  }
  return apiKey;
}

import { normalizeImage } from './shared/images/normalize.js';
import type { ImageNormalizeOptions } from './shared/images/normalize.js';
import { parseImageDataUrlHeader } from './shared/images/policy.js';
import { decodeImageInDom } from './dom/image-decoder.js';

// Loading SVG as an image disables scripts and external subresources.
export async function normalizeSvgImage(dataUrl: unknown, options: Omit<ImageNormalizeOptions, 'decode' | 'signal'> = {}) {
  if (typeof dataUrl !== 'string' || parseImageDataUrlHeader(dataUrl).mimeType !== 'image/svg+xml') throw new Error('Invalid SVG image input');
  return normalizeImage(dataUrl, { ...options, format: options.format || 'png', decode: decodeImageInDom });
}

import { assertImageDimensions, ImageLimitError } from '../shared/images/policy.js';
import { imageT } from '../shared/images/messages.js';

/** SVG uses the image-only DOM decoder, which disables scripts and subresources. */
export async function decodeImageInDom(blob: Blob): Promise<ImageBitmap> {
  if (blob.type !== 'image/svg+xml') return createImageBitmap(blob);
  const url = URL.createObjectURL(blob);
  const image = new Image();
  let timer: ReturnType<typeof setTimeout> | undefined;
  try {
    await new Promise<void>((resolve, reject) => {
      image.onload = () => resolve();
      image.onerror = () => reject(new ImageLimitError('IMAGE_DECODE_FAILED', imageT('decode')));
      timer = setTimeout(() => reject(new ImageLimitError('IMAGE_DECODE_FAILED', imageT('decode'))), 10000);
      image.src = url;
    });
    assertImageDimensions(image.naturalWidth, image.naturalHeight);
    return await createImageBitmap(image);
  } finally { clearTimeout(timer); image.src = ''; URL.revokeObjectURL(url); }
}

import { promptT } from "./i18n/guardrail-prompts.js";
import { t } from "./i18n/backend.js";
import { getEffectiveTabUrl, type TabReference } from "./tab-utils.js";


export interface GuardrailTarget { type: "domain" | "pattern"; value: string }
export interface GuardrailRule extends GuardrailTarget { id: string; action: "block" | "allow"; createdAt: string }
export interface SiteOpenRateLimit extends GuardrailTarget {
  id: string; minOpenIntervalMs: number; enabled: boolean; createdAt: string; updatedAt: string;
}
type GuardrailEntry = (GuardrailRule & { kind: "access" }) | (SiteOpenRateLimit & { kind: "rate_limit" });
export type SecurityGuardrails = ReturnType<typeof normalizeSecurityGuardrails>;
const objectInput = (value: unknown): Record<string, unknown> => value && typeof value === "object" ? value as Record<string, unknown> : {};

export const SECURITY_GUARDRAILS_KEY = "securityGuardrails";
const MAX_GUARDRAIL_PATTERN_LENGTH = 2048;
const GUARDRAIL_ACTIONS = new Set(["block", "allow"]);
const GUARDRAIL_TYPES = new Set(["domain", "pattern"]);
const SITE_OPEN_RATE_LIMIT_MAX_MS = 24 * 60 * 60 * 1000;

export function normalizeGuardrailDomainInput(value: unknown = "") {
  const raw = String(value || "").trim();
  if (!raw) return { domain: "", error: t("security.domainRequired") };

  let text = raw
    .replace(/^@+/, "")
    .replace(/^\*\./, "")
    .trim();

  if (!/^[a-z][a-z0-9+.-]*:\/\//i.test(text)) {
    text = `https://${text}`;
  }

  let host = "";
  try {
    host = new URL(text).hostname;
  } catch (_err) {
    return { domain: "", error: t("security.invalidDomain") };
  }

  const domain = host
    .toLowerCase()
    .replace(/^\*\./, "")
    .replace(/^\.+|\.+$/g, "");

  if (!domain) return { domain: "", error: t("security.invalidDomain") };
  if (!/^[a-z0-9.-]+$/.test(domain)) return { domain: "", error: t("security.domainCharacters") };
  if (domain.includes("..")) return { domain: "", error: t("security.invalidDomain") };
  return { domain, error: "" };
}

export function normalizeGuardrailPatternInput(value: unknown = "") {
  const raw = String(value || "").trim();
  if (!raw) return { pattern: "", error: t("security.patternRequired") };
  if (raw.length > MAX_GUARDRAIL_PATTERN_LENGTH) return { pattern: "", error: t("security.patternTooLong") };
  if (/[\u0000-\u001f\u007f\s]/.test(raw)) return { pattern: "", error: t("security.patternWhitespace") };

  let pattern = raw;
  if (!/^(?:https?|\*):\/\//i.test(pattern)) {
    pattern = `*://${pattern.replace(/^\/+/, "")}`;
  }
  if (!/^(?:https?|\*):\/\/[^/]+(?:\/.*)?$/i.test(pattern)) {
    return { pattern: "", error: t("security.patternDomainRequired") };
  }

  const schemeMatch = pattern.match(/^([^:]+):\/\/(.*)$/);
  const scheme = schemeMatch?.[1] || "";
  const rest = schemeMatch?.[2] || "";
  const slashIndex = rest.indexOf("/");
  const hostPattern = slashIndex >= 0 ? rest.slice(0, slashIndex) : rest;
  const pathPattern = slashIndex >= 0 ? rest.slice(slashIndex) : "/*";
  const normalizedScheme = scheme === "*" ? "*" : scheme.toLowerCase();
  const normalizedHost = hostPattern.toLowerCase().replace(/^\.+|\.+$/g, "");
  if (!/^[a-z0-9.*-]+$/.test(normalizedHost) || normalizedHost.includes("..")) {
    return { pattern: "", error: t("security.patternInvalidDomain") };
  }
  const normalizedPattern = `${normalizedScheme}://${normalizedHost}${pathPattern}`;
  if (normalizedPattern.length > MAX_GUARDRAIL_PATTERN_LENGTH) {
    return { pattern: "", error: t("security.patternTooLong") };
  }
  return { pattern: normalizedPattern, error: "" };
}

export function normalizeSecurityGuardrails(input: unknown = {}) {
  const value = objectInput(input);
  const rawOrderedRules = Array.isArray(value?.rules) ? value.rules : [];
  const rawRules = Array.isArray(value?.blockedDomains) ? value.blockedDomains : [];
  const rawPatterns = Array.isArray(value?.blockedPatterns) ? value.blockedPatterns : [];
  const rawSiteOpenRateLimits = Array.isArray(value?.siteOpenRateLimits)
    ? value.siteOpenRateLimits
    : (Array.isArray(value?.navigationRateLimits) ? value.navigationRateLimits : []);
  const seenRules = new Set();
  const rules: GuardrailRule[] = [];
  const seenSiteOpenRateLimits = new Set();
  const siteOpenRateLimits: SiteOpenRateLimit[] = [];

  const pushRule = (source: unknown) => {
    const normalized = normalizeGuardrailRuleInput(source);
    if (!normalized.rule) return;
    const key = `${normalized.rule.action}:${normalized.rule.type}:${normalized.rule.value}`;
    if (seenRules.has(key)) return;
    seenRules.add(key);
    rules.push(normalized.rule);
  };

  rawOrderedRules.forEach(pushRule);

  rawRules.forEach((item) => {
    const source: Record<string, unknown> = typeof item === "string" ? { domain: item } : objectInput(item);
    pushRule({ ...source, action: "block", type: "domain", value: source.domain || source.host || source.value || "" });
  });

  rawPatterns.forEach((item) => {
    const source: Record<string, unknown> = typeof item === "string" ? { pattern: item } : objectInput(item);
    pushRule({ ...source, action: "block", type: "pattern", value: source.pattern || source.value || "" });
  });

  rawSiteOpenRateLimits.forEach((item) => {
    const normalized = normalizeSiteOpenRateLimitInput(item);
    if (!normalized.rateLimit) return;
    const key = `${normalized.rateLimit.type}:${normalized.rateLimit.value}`;
    if (seenSiteOpenRateLimits.has(key)) return;
    seenSiteOpenRateLimits.add(key);
    siteOpenRateLimits.push(normalized.rateLimit);
  });

  const inputOrder = normalizeSecurityGuardrailOrderInput(value?.order || value?.ruleOrder);
  applySecurityGuardrailOrder(rules, inputOrder);
  applySecurityGuardrailOrder(siteOpenRateLimits, inputOrder);
  const knownIds = new Set([
    ...rules.map(item => item.id),
    ...siteOpenRateLimits.map(item => item.id),
  ]);
  const order = [
    ...inputOrder.filter((id, index) => knownIds.has(id) && inputOrder.indexOf(id) === index),
    ...rules.map(item => item.id).filter(id => !inputOrder.includes(id)),
    ...siteOpenRateLimits.map(item => item.id).filter(id => !inputOrder.includes(id)),
  ];

  const blockedDomains = rules
    .filter(rule => rule.action === "block" && rule.type === "domain")
    .map(rule => ({ domain: rule.value, createdAt: rule.createdAt, id: rule.id }));
  const blockedPatterns = rules
    .filter(rule => rule.action === "block" && rule.type === "pattern")
    .map(rule => ({ pattern: rule.value, createdAt: rule.createdAt, id: rule.id }));
  const allowedDomains = rules
    .filter(rule => rule.action === "allow" && rule.type === "domain")
    .map(rule => ({ domain: rule.value, createdAt: rule.createdAt, id: rule.id }));
  const allowedPatterns = rules
    .filter(rule => rule.action === "allow" && rule.type === "pattern")
    .map(rule => ({ pattern: rule.value, createdAt: rule.createdAt, id: rule.id }));

  return { rules, blockedDomains, blockedPatterns, allowedDomains, allowedPatterns, siteOpenRateLimits, order };
}

export async function getSecurityGuardrails() {
  const { [SECURITY_GUARDRAILS_KEY]: stored = {} } = await chrome.storage.local.get(SECURITY_GUARDRAILS_KEY);
  return normalizeSecurityGuardrails(stored);
}

export async function saveSecurityGuardrails(value: unknown = {}) {
  const guardrails = normalizeSecurityGuardrails(value);
  await chrome.storage.local.set({ [SECURITY_GUARDRAILS_KEY]: guardrails });
  return guardrails;
}

export function normalizeGuardrailRuleInput(input: unknown = {}): { rule: GuardrailRule | null; error: string } {
  const source: Record<string, unknown> = typeof input === "string" ? { action: "block", type: "domain", value: input } : objectInput(input);
  const action = String(source.action || "").trim() === "allow" ? "allow" : "block";
  const requestedType = String(source.type || "").trim();
  const type = requestedType === "pattern" || requestedType === "domain" ? requestedType : inferGuardrailRuleType(source);
  const rawValue = source.value || source.domain || source.host || source.pattern || "";
  const normalized = type === "pattern"
    ? normalizeGuardrailPatternInput(rawValue)
    : normalizeGuardrailDomainInput(rawValue);
  if (normalized.error) return { rule: null, error: normalized.error };
  const value = "pattern" in normalized ? normalized.pattern : normalized.domain;
  return {
    rule: {
      id: normalizeGuardrailRuleId(source.id, { action, type, value }),
      action,
      type,
      value,
      createdAt: String(source.createdAt || new Date().toISOString()),
    },
    error: "",
  };
}

export function normalizeSiteOpenRateLimitInput(input: unknown = {}): { rateLimit: SiteOpenRateLimit | null; error: string } {
  const source: Record<string, unknown> = typeof input === "string" ? { type: "domain", value: input } : objectInput(input);
  const requestedType = String(source.type || "").trim();
  const type = requestedType === "pattern" || requestedType === "domain" ? requestedType : inferGuardrailRuleType(source);
  const rawValue = source.value || source.domain || source.host || source.pattern || "";
  const normalizedTarget = type === "pattern"
    ? normalizeGuardrailPatternInput(rawValue)
    : normalizeGuardrailDomainInput(rawValue);
  if (normalizedTarget.error) return { rateLimit: null, error: normalizedTarget.error };

  const minOpenIntervalMs = normalizeSiteOpenRateLimitIntervalMs(
    source.minOpenIntervalMs
      ?? source.minIntervalMs
      ?? source.intervalMs
      ?? source.openIntervalMs
      ?? source.waitMs,
  );
  if (minOpenIntervalMs.error) return { rateLimit: null, error: minOpenIntervalMs.error };

  const value = "pattern" in normalizedTarget ? normalizedTarget.pattern : normalizedTarget.domain;
  return {
    rateLimit: {
      id: normalizeSiteOpenRateLimitId(source.id, { type, value }),
      type,
      value,
      minOpenIntervalMs: minOpenIntervalMs.value,
      enabled: source.enabled !== false,
      createdAt: String(source.createdAt || new Date().toISOString()),
      updatedAt: String(source.updatedAt || source.createdAt || new Date().toISOString()),
    },
    error: "",
  };
}

export async function addSecurityGuardrailRule(input: unknown = {}) {
  const normalized = normalizeGuardrailRuleInput(input);
  if (!normalized.rule) return { ok: false, error: normalized.error, rule: null, guardrails: await getSecurityGuardrails() };

  const guardrails = await getSecurityGuardrails();
  const target = normalized.rule;
  const exists = guardrails.rules.some(rule => (
    rule.action === target.action
    && rule.type === target.type
    && rule.value === target.value
  ));
  if (exists) return { ok: true, existed: true, rule: normalized.rule, guardrails };

  const next = await saveSecurityGuardrails({
    rules: [
      ...guardrails.rules,
      normalized.rule,
    ],
    siteOpenRateLimits: guardrails.siteOpenRateLimits,
    order: [...guardrails.order, normalized.rule.id],
  });
  return { ok: true, existed: false, rule: normalized.rule, guardrails: next };
}

export async function removeSecurityGuardrailRule(idOrRule: unknown = "") {
  const guardrails = await getSecurityGuardrails();
  const id = typeof idOrRule === "string" ? idOrRule : String(objectInput(idOrRule).id || "");
  const normalized = !id && idOrRule && typeof idOrRule === "object"
    ? normalizeGuardrailRuleInput(idOrRule)
    : null;
  const nextRules = guardrails.rules.filter((rule) => {
    if (id && rule.id === id) return false;
    if (!normalized?.rule) return true;
    return !(rule.action === normalized.rule.action && rule.type === normalized.rule.type && rule.value === normalized.rule.value);
  });
  const next = await saveSecurityGuardrails({
    rules: nextRules,
    siteOpenRateLimits: guardrails.siteOpenRateLimits,
    order: guardrails.order.filter(ruleId => nextRules.some(rule => rule.id === ruleId) || guardrails.siteOpenRateLimits.some(item => item.id === ruleId)),
  });
  return { ok: true, id, guardrails: next };
}

export async function reorderSecurityGuardrailRules(ruleIds: unknown = []) {
  const ids = Array.isArray(ruleIds) ? ruleIds.map(id => String(id || "")).filter(Boolean) : [];
  const guardrails = await getSecurityGuardrails();
  const byId = new Map(guardrails.rules.map(rule => [rule.id, rule]));
  const ordered: GuardrailRule[] = [];
  ids.forEach((id) => {
    const rule = byId.get(id);
    if (!rule) return;
    ordered.push(rule);
    byId.delete(id);
  });
  const nextRules = [...ordered, ...byId.values()];
  const rateLimitIds = new Set(guardrails.siteOpenRateLimits.map(item => item.id));
  const next = await saveSecurityGuardrails({
    rules: nextRules,
    siteOpenRateLimits: guardrails.siteOpenRateLimits,
    order: [
      ...nextRules.map(rule => rule.id),
      ...guardrails.order.filter(id => rateLimitIds.has(id)),
    ],
  });
  return { ok: true, guardrails: next };
}

export async function addSecurityGuardrailDomain(value: unknown = "") {
  const result = await addSecurityGuardrailRule({ action: "block", type: "domain", value });
  return { ...result, domain: result.rule?.value || "" };
}

export async function addSecurityGuardrailPattern(value: unknown = "") {
  const result = await addSecurityGuardrailRule({ action: "block", type: "pattern", value });
  return { ...result, pattern: result.rule?.value || "" };
}

export async function removeSecurityGuardrailDomain(value: unknown = "") {
  const normalized = normalizeGuardrailDomainInput(value);
  const domain = normalized.domain || String(value || "").trim().toLowerCase();
  const result = await removeSecurityGuardrailRule({ action: "block", type: "domain", value: domain });
  return { ...result, domain };
}

export async function removeSecurityGuardrailPattern(value: unknown = "") {
  const normalized = normalizeGuardrailPatternInput(value);
  const pattern = normalized.pattern || String(value || "").trim();
  const result = await removeSecurityGuardrailRule({ action: "block", type: "pattern", value: pattern });
  return { ...result, pattern };
}

export interface GuardrailDecision {
  blocked: boolean; allowed: boolean; action: "block" | "allow";
  type: "domain" | "pattern"; matchType: "domain" | "pattern";
  domain?: string; pattern?: string; value: string; ruleId: string; host: string; url: string;
}

export function matchSecurityGuardrailUrl(url: unknown = "", guardrails: unknown = {}): GuardrailDecision | null {
  const target = parseGuardrailUrl(url);
  if (!target) return null;
  const { parsed, host, normalizedUrl } = target;
  const normalized = normalizeSecurityGuardrails(guardrails);
  const matchingRules = normalized.rules.filter(item => securityGuardrailRuleMatches(item, host, normalizedUrl));
  const rule = matchingRules[0] || null;
  if (rule) {
    return {
      blocked: rule.action === "block",
      allowed: rule.action === "allow",
      action: rule.action,
      type: rule.type,
      matchType: rule.type,
      domain: rule.type === "domain" ? rule.value : undefined,
      pattern: rule.type === "pattern" ? rule.value : undefined,
      value: rule.value,
      ruleId: rule.id,
      host,
      url: parsed.href,
    };
  }
  return null;
}

export function matchBlockedUrl(url: unknown = "", guardrails: unknown = {}) {
  const decision = matchSecurityGuardrailUrl(url, guardrails);
  return decision?.blocked ? decision : null;
}

export function matchSiteOpenRateLimitUrl(url: unknown = "", guardrails: unknown = {}) {
  const target = parseGuardrailUrl(url);
  if (!target) return null;
  const { parsed, host, normalizedUrl } = target;
  const normalized = normalizeSecurityGuardrails(guardrails);
  const matches = normalized.siteOpenRateLimits.filter(item => (
    item?.enabled !== false
    && securityGuardrailTargetMatches(item, host, normalizedUrl)
  ));
  if (!matches.length) return null;

  const rateLimit = matches[0];
  return {
    type: rateLimit.type,
    matchType: rateLimit.type,
    domain: rateLimit.type === "domain" ? rateLimit.value : undefined,
    pattern: rateLimit.type === "pattern" ? rateLimit.value : undefined,
    value: rateLimit.value,
    ruleId: rateLimit.id,
    host,
    url: parsed.href,
    minOpenIntervalMs: Number(rateLimit.minOpenIntervalMs || 0),
  };
}

export function filterAllowedTabs<T extends TabReference>(tabs: readonly T[] = [], guardrails: unknown = {}): T[] {
  return (Array.isArray(tabs) ? tabs : []).filter((tab) => {
    const url = getEffectiveTabUrl(tab);
    return !matchBlockedUrl(url, guardrails);
  });
}

export function annotateSecurityGuardrailTab<T extends TabReference>(tab: T, guardrails: unknown = {}): T & {
  securityGuardrailBlocked?: boolean; contentAccess?: string;
  securityGuardrail?: Pick<NonNullable<ReturnType<typeof matchBlockedUrl>>, "action" | "type" | "value" | "domain" | "pattern" | "ruleId">;
} {
  const match = matchBlockedUrl(getEffectiveTabUrl(tab), guardrails);
  if (!match) return { ...tab };
  return {
    ...tab,
    securityGuardrailBlocked: true,
    contentAccess: "blocked",
    securityGuardrail: {
      action: "block",
      type: match.type,
      value: match.value,
      domain: match.domain,
      pattern: match.pattern,
      ruleId: match.ruleId,
    },
  };
}

export function annotateSecurityGuardrailTabs<T extends TabReference>(tabs: readonly T[] = [], guardrails: unknown = {}) {
  return (Array.isArray(tabs) ? tabs : []).map(tab => annotateSecurityGuardrailTab(tab, guardrails));
}

export function buildSecurityGuardrailPromptSection(guardrails: unknown = {}, { limit = 30 } = {}) {
  const normalized = normalizeSecurityGuardrails(guardrails);
  const byId = buildSecurityGuardrailEntryMap(normalized);
  const entries = normalized.order
    .map(id => byId.get(id))
    .filter((item): item is GuardrailEntry => Boolean(item && (item.kind !== "rate_limit" || item.enabled !== false)));
  const listed = entries.slice(0, limit);
  const remaining = Math.max(0, entries.length - listed.length);
  if (!listed.length) return "";

  const lines = ["", promptT("heading"), promptT("policy")];
  for (const entry of listed) {
    const type = entry.type === "pattern" ? promptT("pattern") : promptT("domain");
    const suffix = entry.type === "domain" ? promptT("subdomains") : "";
    if (entry.kind === "rate_limit") {
      lines.push(promptT("rateLimit", { type, value: entry.value, suffix, interval: formatDurationMsForPrompt(entry.minOpenIntervalMs) }));
      continue;
    }
    const action = entry.action === "allow" ? promptT("allow") : promptT("block");
    lines.push(`- ${action} / ${type}: ${entry.value}${suffix}`);
  }
  if (remaining > 0) lines.push(promptT("remaining", { count: remaining }));
  return `${lines.join("\n")}\n`;
}

function buildSecurityGuardrailEntryMap(guardrails: SecurityGuardrails) {
  return new Map<string, GuardrailEntry>([
    ...guardrails.rules.map(rule => [rule.id, { ...rule, kind: "access" } as const] as const),
    ...guardrails.siteOpenRateLimits.map(item => [item.id, { ...item, kind: "rate_limit" } as const] as const),
  ]);
}

function inferGuardrailRuleType(source: Record<string, unknown> = {}) {
  if (source.pattern != null) return "pattern";
  return "domain";
}

function normalizeSecurityGuardrailOrderInput(value: unknown = []) {
  if (!Array.isArray(value)) return [];
  const seen = new Set();
  const order = [];
  for (const item of value) {
    const id = String(item || "").trim();
    if (!id || seen.has(id)) continue;
    seen.add(id);
    order.push(id);
  }
  return order;
}

function applySecurityGuardrailOrder(items: { id: string }[], order: string[] = []) {
  if (!Array.isArray(items) || !items.length || !order.length) return;
  const indexById = new Map(order.map((id, index) => [id, index]));
  items.sort((a, b) => {
    const left = indexById.get(a.id) ?? Number.POSITIVE_INFINITY;
    const right = indexById.get(b.id) ?? Number.POSITIVE_INFINITY;
    return left - right;
  });
}

function normalizeGuardrailRuleId(id: unknown, { action, type, value }: Pick<GuardrailRule, "action" | "type" | "value">) {
  const raw = String(id || "").trim();
  if (raw) return raw;
  return `guard_${action}_${type}_${hashGuardrailRuleValue(value)}`;
}

function normalizeSiteOpenRateLimitId(id: unknown, { type, value }: GuardrailTarget) {
  const raw = String(id || "").trim();
  if (raw) return raw;
  return `guard_open_rate_${type}_${hashGuardrailRuleValue(value)}`;
}

function normalizeSiteOpenRateLimitIntervalMs(value: unknown) {
  const number = Number(value);
  if (!Number.isFinite(number) || number <= 0) return { value: 0, error: t("security.intervalPositive") };
  const rounded = Math.round(number);
  if (rounded > SITE_OPEN_RATE_LIMIT_MAX_MS) return { value: 0, error: t("security.intervalTooLong") };
  return { value: rounded, error: "" };
}

function hashGuardrailRuleValue(value: unknown = "") {
  const text = String(value || "");
  let hash = 2166136261;
  for (let i = 0; i < text.length; i += 1) {
    hash ^= text.charCodeAt(i);
    hash = Math.imul(hash, 16777619);
  }
  return (hash >>> 0).toString(36);
}

function securityGuardrailRuleMatches(rule: GuardrailRule, host: string, normalizedUrl: string) {
  if (!rule || !GUARDRAIL_ACTIONS.has(rule.action) || !GUARDRAIL_TYPES.has(rule.type)) return false;
  return securityGuardrailTargetMatches(rule, host, normalizedUrl);
}

function securityGuardrailTargetMatches(target: GuardrailTarget, host: string, normalizedUrl: string) {
  if (!target || !GUARDRAIL_TYPES.has(target.type)) return false;
  if (target.type === "domain") return host === target.value || host.endsWith(`.${target.value}`);
  try {
    const pattern = target.value.match(/^(\*|https?):\/\/([^/]+)(\/.*)$/);
    if (!pattern) return false;
    const url = new URL(normalizedUrl);
    return (pattern[1] === "*" || `${pattern[1]}:` === url.protocol)
      && matchesWildcard(url.host, pattern[2])
      && matchesWildcard(`${url.pathname}${url.search}${url.hash}`, pattern[3]);
  } catch (_err) {
    return false;
  }
}

function parseGuardrailUrl(url: unknown) {
  try {
    const parsed = new URL(String(url || ""));
    if (!["http:", "https:"].includes(parsed.protocol) || !parsed.hostname) return null;
    return { parsed, host: parsed.hostname.toLowerCase(), normalizedUrl: normalizeUrlForPatternMatch(parsed) };
  } catch { return null; }
}

function normalizeUrlForPatternMatch(parsed: URL) {
  const protocol = parsed.protocol.toLowerCase();
  const host = parsed.host.toLowerCase();
  return `${protocol}//${host}${parsed.pathname}${parsed.search}${parsed.hash}`;
}

function matchesWildcard(value: string, pattern: string) {
  const parts = pattern.split("*");
  if (parts.length === 1) return value === pattern;
  if (!value.startsWith(parts[0])) return false;
  let offset = parts[0].length;
  for (const part of parts.slice(1, -1)) {
    const index = value.indexOf(part, offset);
    if (index < 0) return false;
    offset = index + part.length;
  }
  const last = parts[parts.length - 1];
  return value.endsWith(last) && value.length - last.length >= offset;
}

function formatDurationMsForPrompt(ms: unknown = 0) {
  const value = Number(ms) || 0;
  if (value >= 60 * 1000 && value % (60 * 1000) === 0) return promptT("minutes", { value: value / (60 * 1000) });
  if (value >= 1000 && value % 1000 === 0) return promptT("seconds", { value: value / 1000 });
  return `${value} ms`;
}

import type { ModelMessage } from './protocol-registry.js';
import { normalizeImage } from '../../shared/images/normalize.js';
import { MODEL_IMAGE_MAX_BYTES, MODEL_REQUEST_MAX_BYTES } from '../../shared/images/policy.js';
import { defineMessages } from '../../shared/i18n/definition.js';
import { createTranslator } from '../../shared/i18n/index.js';
import { utf8ByteLength } from '../../shared/transport/message-codec.js';

const t = createTranslator(defineMessages('model-payload', {
  images: { 'zh-CN': '模型请求的图片总大小超出上限，请减少图片或压缩上下文后重试。', en: 'The model request contains too much image data. Remove images or compact the context and try again.' },
  remote: { 'zh-CN': '请先使用图片读取工具加载这张图片，再发送给模型。', en: 'Load this image with an image-reading tool before sending it to the model.' },
  request: { 'zh-CN': '模型请求过大，请压缩上下文或开始新任务。', en: 'The model request is too large. Compact the context or start a new task.' },
}));

function failure(code: string, message: string) {
  return Object.assign(new Error(message), { name: 'ModelPayloadError', kind: 'invalid_request', code, retryable: false });
}

/** Normalize model copies without changing stored history or dropping requested images. */
export async function prepareModelImages(messages: ModelMessage[], signal?: AbortSignal,
  normalize: typeof normalizeImage = normalizeImage): Promise<ModelMessage[]> {
  let bytes = 0;
  let result = messages;
  // Repeated references reuse the decode only within this request; nothing retains historical bitmaps.
  const normalized = new Map<string, Awaited<ReturnType<typeof normalizeImage>>>();
  for (let i = messages.length - 1; i >= 0; i--) {
    signal?.throwIfAborted();
    const content = messages[i].content;
    if (!Array.isArray(content)) continue;
    const parts = content.slice();
    for (let j = content.length - 1; j >= 0; j--) {
      const part = content[j];
      if (part?.type !== 'image_url' || typeof part.image_url?.url !== 'string') continue;
      const url: string = part.image_url.url;
      // Remote fetching belongs to the safety-checked image tool, not the provider adapter.
      if (!url.startsWith('data:')) throw failure('MODEL_IMAGE_NOT_LOADED', t('remote'));
      const image = normalized.get(url) || await normalize(url, { signal });
      normalized.set(url, image);
      if (bytes + image.bytes > MODEL_IMAGE_MAX_BYTES) {
        throw failure('MODEL_IMAGES_TOO_LARGE', t('images'));
      } else {
        bytes += image.bytes;
        parts[j] = { ...part, image_url: { ...part.image_url, url: image.dataUrl } };
      }
    }
    if (parts.some((part, index) => part !== content[index])) {
      if (result === messages) result = messages.slice();
      result[i] = { ...messages[i], content: parts };
    }
  }
  return result;
}

/** Check the final adapter body, including base64, text, schemas and protocol overhead. */
export function assertModelRequestSize(body: RequestInit['body']) {
  const bytes = typeof body === 'string' ? utf8ByteLength(body)
    : body instanceof Blob ? body.size
    : body instanceof ArrayBuffer ? body.byteLength
    : ArrayBuffer.isView(body) ? body.byteLength : 0;
  if (bytes > MODEL_REQUEST_MAX_BYTES) throw failure('MODEL_REQUEST_TOO_LARGE', t('request'));
}

import { t } from "./i18n.js";
import { positiveArtifactNumber as positive, resolveArtifactUpdatedAt, type ToolArtifactAdapter } from "#sdk/shared/artifacts";
const normalize: ToolArtifactAdapter["normalize"] = artifact => {
  if (!artifact.table || artifact.type !== "data") return artifact;
  // These tools authored the count caption; keep user titles and regenerate the caption from rowCount.
  return { ...artifact, kind: "image_collection", kindLabel: t("imageCollection"), meta: undefined };
};
const adapter: ToolArtifactAdapter = { normalize, project(args, result, consumer) {
  // Old UI timelines only showed collections with an explicit envelope; authoritative context also inferred them.
  if (consumer === "display") return [];
  const table = String(result.table || args.table || "").trim();
  if (!table) return [];
  const totalRows = positive(result.totalRows ?? result.collected ?? result.inserted ?? result.updated);
  return [{
    type: "data", kind: "image_collection", sourceTool: "collect_images", id: table, table, title: table, totalRows, score: 3,
    ...(consumer === "resource" ? {
      kindLabel: t("imageCollection"), rowCount: totalRows,
      ...(Array.isArray(result.assetIds) ? { assetCount: result.assetIds.length } : {}),
    } : { action: "collect_images", updatedAt: resolveArtifactUpdatedAt(result) }),
  }];
} };
export default { collect_images: adapter, screenshot: { normalize } };

/** Background preserves attachment records while parsing is in flight. Each client validates its own projection. */
export interface ComposerDraft<Image = Record<string, unknown>, Document = Record<string, unknown>> {
  sessionId: string | null;
  messageId: string;
  text: string;
  images: Image[];
  documents: Document[];
  updatedAt: number;
}

import { t, tHtml } from "../i18n/index.js";
type DialogMode = "confirm" | "choice" | "input";
type DialogResult = boolean | string | null;
interface DialogInput {
  title?: unknown; message?: unknown; confirmLabel?: unknown; cancelLabel?: unknown; tone?: unknown;
  choices?: unknown; inputLabel?: unknown; value?: unknown; placeholder?: unknown; required?: unknown; maxLength?: unknown;
  signal?: AbortSignal;
}
type Config = ReturnType<typeof normalizeConfig>;
interface Elements {
  dialog: HTMLDialogElement; panel: HTMLElement; title: HTMLElement; message: HTMLElement; options: HTMLElement;
  inputGroup: HTMLElement; inputLabel: HTMLElement; input: HTMLInputElement; cancel: HTMLButtonElement; confirm: HTMLButtonElement;
}
interface ActiveDialog { config: Config; previousFocus: HTMLElement | null; resolve(result: DialogResult): void; settling: boolean; timer?: ReturnType<typeof setTimeout> }

const DIALOG_CLOSE_MS = 180;

export function createDecisionDialogFeature(options: { root?: Document | Element; shouldReduceMotion?: () => boolean; hideToast?: () => unknown } = {}) {
  const root = options.root || document;
  const documentRef = "createElement" in root ? root : root.ownerDocument || document;
  const shouldReduceMotion = options.shouldReduceMotion || (() => (
    globalThis.matchMedia?.("(prefers-reduced-motion: reduce)")?.matches === true
  ));
  const hideToast = options.hideToast || (() => {});
  let queue: Promise<unknown> = Promise.resolve();
  let active: ActiveDialog | null = null;
  let elements: Elements | null = null;

  function confirm(messageOrOptions: unknown, input: DialogInput = {}) {
    const config = normalizeConfig("confirm", messageOrOptions, input);
    return enqueue(config).then(result => result === true);
  }

  function choose(input: DialogInput = {}) {
    const config = normalizeConfig("choice", input, {});
    return enqueue(config).then(result => typeof result === "string" ? result : null);
  }

  function requestText(input: DialogInput = {}) {
    const config = normalizeConfig("input", input, {});
    return enqueue(config).then(result => typeof result === "string" ? result : null);
  }

  function enqueue(config: Config) {
    if (config.signal?.aborted) return Promise.resolve(null);
    const result = queue.then(() => open(config));
    queue = result.catch(() => null);
    const signal = config.signal;
    if (!signal) return result;
    return new Promise<DialogResult>((resolve, reject) => {
      const cancel = () => {
        if (active?.config === config) settle(null, true);
        signal.removeEventListener("abort", cancel);
        resolve(null);
      };
      signal.addEventListener("abort", cancel, { once: true });
      result.then(resolve, reject).finally(() => signal.removeEventListener("abort", cancel));
    });
  }

  function open(config: Config): Promise<DialogResult> {
    if (config.signal?.aborted) return Promise.resolve(null);
    const ui = ensureElements();
    if (typeof ui.dialog.showModal !== "function") {
      return Promise.resolve(config.mode === "confirm" ? false : null);
    }

    const HTMLElementRef = documentRef.defaultView?.HTMLElement;
    const previousFocus = HTMLElementRef && documentRef.activeElement instanceof HTMLElementRef
      ? documentRef.activeElement
      : null;
    hideToast();
    ui.dialog.dataset.mode = config.mode;
    ui.dialog.dataset.tone = config.tone;
    ui.dialog.classList.remove("is-closing");
    ui.title.textContent = config.title;
    ui.message.textContent = config.message;
    ui.message.classList.toggle("hidden", !config.message);
    ui.dialog.toggleAttribute("aria-describedby", Boolean(config.message));
    if (config.message) ui.dialog.setAttribute("aria-describedby", ui.message.id);
    ui.cancel.textContent = config.cancelLabel;
    ui.confirm.textContent = config.confirmLabel;
    ui.confirm.className = `qz-btn ${config.tone === "danger" ? "qz-btn--danger" : "qz-btn--primary"} qz-btn--sm`;
    ui.confirm.classList.toggle("hidden", config.mode === "choice");
    renderChoices(ui, config.choices);
    ui.options.classList.toggle("hidden", config.mode !== "choice");
    ui.inputGroup.classList.toggle("hidden", config.mode !== "input");
    ui.inputLabel.textContent = config.inputLabel;
    ui.input.value = config.value;
    ui.input.placeholder = config.placeholder;
    ui.input.maxLength = config.maxLength;
    syncInputState(ui, config);

    return new Promise<DialogResult>(resolve => {
      active = {
        config,
        previousFocus,
        resolve,
        settling: false,
      };
      ui.dialog.showModal();
      requestFrame(() => {
        if (active?.config !== config || active.settling) return;
        const target = config.mode === "choice"
          ? ui.options.querySelector<HTMLElement>(".qz-decision-option")
          : config.mode === "input" ? ui.input
          : config.tone === "danger" ? ui.cancel : ui.confirm;
        target?.focus?.({ preventScroll: true });
        if (target === ui.input) ui.input.select();
      });
    });
  }

  function ensureElements(): Elements {
    if (elements?.dialog?.isConnected) return elements;
    const dialog = documentRef.createElement("dialog");
    dialog.id = "qz-decision-dialog";
    dialog.className = "qz-decision-dialog";
    dialog.setAttribute("aria-labelledby", "qz-decision-title");
    dialog.innerHTML = `
      <section class="qz-decision-panel">
        <header class="qz-decision-copy">
          <h3 id="qz-decision-title" data-qz-decision-title></h3>
          <p id="qz-decision-message" data-qz-decision-message></p>
        </header>
        <div id="qz-decision-options" class="qz-decision-options hidden" role="group" aria-label="${tHtml("availableActions")}" data-qz-decision-options></div>
        <label class="qz-decision-input hidden" data-qz-decision-input-group>
          <span class="qz-field-label" data-qz-decision-input-label></span>
          <input class="qz-field qz-field--sm" type="text" autocomplete="off" data-qz-decision-input>
        </label>
        <footer class="qz-decision-actions">
          <button id="qz-decision-cancel" class="qz-btn qz-btn--ghost qz-btn--sm" type="button" data-qz-decision-cancel>${tHtml("cancel")}</button>
          <button id="qz-decision-confirm" class="qz-btn qz-btn--primary qz-btn--sm" type="button" data-qz-decision-confirm>${tHtml("confirm")}</button>
        </footer>
      </section>
    `;
    documentRef.body.append(dialog);
    elements = {
      dialog,
      panel: dialog.querySelector<HTMLElement>(".qz-decision-panel")!,
      title: dialog.querySelector<HTMLElement>("[data-qz-decision-title]")!,
      message: dialog.querySelector<HTMLElement>("[data-qz-decision-message]")!,
      options: dialog.querySelector<HTMLElement>("[data-qz-decision-options]")!,
      inputGroup: dialog.querySelector<HTMLElement>("[data-qz-decision-input-group]")!,
      inputLabel: dialog.querySelector<HTMLElement>("[data-qz-decision-input-label]")!,
      input: dialog.querySelector<HTMLInputElement>("[data-qz-decision-input]")!,
      cancel: dialog.querySelector<HTMLButtonElement>("[data-qz-decision-cancel]")!,
      confirm: dialog.querySelector<HTMLButtonElement>("[data-qz-decision-confirm]")!,
    };
    const ui = elements;
    ui.cancel.addEventListener("click", () => settle(null));
    ui.confirm.addEventListener("click", () => {
      if (active?.config.mode === "input") settle(ui.input.value.trim());
      else settle(true);
    });
    ui.input.addEventListener("input", () => {
      if (active?.config.mode === "input") syncInputState(ui, active.config);
    });
    ui.input.addEventListener("keydown", (event) => {
      if (event.key !== "Enter" || event.isComposing || event.shiftKey || event.altKey || event.ctrlKey || event.metaKey) return;
      event.preventDefault();
      if (!ui.confirm.disabled) settle(ui.input.value.trim());
    });
    dialog.addEventListener("cancel", (event) => {
      event.preventDefault();
      settle(null);
    });
    dialog.addEventListener("click", (event) => {
      if (event.target === dialog) settle(null);
    });
    return elements;
  }

  function renderChoices(ui: Elements, choices: Config["choices"]) {
    ui.options.replaceChildren();
    for (const choice of choices) {
      const button = documentRef.createElement("button");
      button.type = "button";
      button.className = `qz-btn qz-btn--ghost qz-decision-option${choice.tone === "danger" ? " qz-btn--danger" : ""}`;
      button.dataset.qzDecisionValue = choice.value;
      const label = documentRef.createElement("strong");
      label.textContent = choice.label;
      button.append(label);
      if (choice.description) {
        const description = documentRef.createElement("small");
        description.textContent = choice.description;
        button.append(description);
      }
      button.addEventListener("click", () => settle(choice.value));
      ui.options.append(button);
    }
  }

  function settle(result: DialogResult, cancelled = false) {
    const state = active;
    if (!state || (state.settling && !cancelled)) return;
    if (state.timer) clearTimeout(state.timer);
    state.settling = true;
    const ui = ensureElements();
    ui.dialog.classList.add("is-closing");
    const finish = () => {
      if (ui.dialog.open) ui.dialog.close();
      ui.dialog.classList.remove("is-closing");
      ui.options.replaceChildren();
      ui.input.value = "";
      active = null;
      if (!cancelled) state.previousFocus?.focus?.({ preventScroll: true });
      if (state.config.mode === "choice" || state.config.mode === "input") {
        state.resolve(typeof result === "string" ? result : null);
      } else {
        state.resolve(result === true);
      }
    };
    if (cancelled) finish();
    else state.timer = setTimeout(finish, shouldReduceMotion() ? 0 : DIALOG_CLOSE_MS);
  }

  return Object.freeze({ confirm, choose, requestText });
}

function normalizeConfig(mode: DialogMode, messageOrOptions: unknown, options: DialogInput) {
  const raw = typeof messageOrOptions === "object" && messageOrOptions
    ? messageOrOptions as DialogInput
    : { ...options, message: messageOrOptions };
  return {
    mode,
    signal: options.signal || raw.signal,
    title: String(raw.title || (mode === "choice" ? t("pleaseSelect") : mode === "input" ? t("enterContent") : t("confirmAction"))).trim(),
    message: String(raw.message || "").trim(),
    confirmLabel: String(raw.confirmLabel || t("confirm")).trim(),
    cancelLabel: String(raw.cancelLabel || t("cancel")).trim(),
    tone: raw.tone === "danger" ? "danger" : "neutral",
    choices: normalizeChoices(raw.choices),
    inputLabel: String(raw.inputLabel || "").trim(),
    value: String(raw.value || ""),
    placeholder: String(raw.placeholder || ""),
    required: raw.required !== false,
    maxLength: normalizeMaxLength(raw.maxLength),
  };
}

function normalizeChoices(value: unknown) {
  if (!Array.isArray(value)) return [];
  return value.slice(0, 8).map((choice, index) => ({
    value: String(choice?.value || `choice-${index + 1}`),
    label: String(choice?.label || choice?.value || t("optionNumber", { number: index + 1 })),
    description: String(choice?.description || ""),
    tone: choice?.tone === "danger" ? "danger" : "neutral",
  }));
}

function requestFrame(callback: FrameRequestCallback) {
  if (typeof globalThis.requestAnimationFrame === "function") {
    globalThis.requestAnimationFrame(callback);
  } else {
    setTimeout(() => callback(Date.now()), 0);
  }
}

function syncInputState(ui: Elements, config: Config) {
  ui.confirm.disabled = config.mode === "input" && config.required && !ui.input.value.trim();
}

function normalizeMaxLength(value: unknown) {
  const parsed = Number(value || 200);
  if (!Number.isFinite(parsed)) return 200;
  return Math.max(1, Math.min(2000, Math.round(parsed)));
}

